// StaffLogs 获取账户日志
func StaffLogs(ctx context.Context, req model.StaffLogsReq) (resp model.StaffLogsResp, err error) {
	var (
		logQ    = sqlmodel.AdminLogColumns
		logs    []sqlmodel.AdminLog
		userIDs []int64
		params  = make([]clause.Expression, 0)
	)
	if req.StaffID > 0 {
		params = append(params, logQ.UserID.Eq(req.StaffID))
	}
	if req.DateStart != "" {
		star, _ := time.ParseInLocation("2006-01-02", req.DateStart, time.Local)
		params = append(params, logQ.CreateAt.Gte(star.Unix()))
	}
	if req.DateEnd != "" {
		end, _ := time.ParseInLocation("2006-01-02", req.DateEnd, time.Local)
		params = append(params, logQ.CreateAt.Lte(end.Unix()+86400-1))
	}
	resp.Total, err = dao.CountAdminLog(ctx, dao.And(params...))
	if err != nil {
		return
	}
	resp.List = make([]model.StaffLogItem, 0)
	err = dao.FetchAllAdminLog(ctx, &logs, dao.And(params...), req.Page, req.Size, logQ.ID.Desc())
	if err != nil {
		return
	}
	if len(logs) == 0 {
		return
	}
	for _, log := range logs {
		userIDs = append(userIDs, log.UserID)
	}
	userMap := handler.GetUserMap(ctx, userIDs)
	for _, log := range logs {
		user := userMap[log.UserID]
		resp.List = append(resp.List, model.StaffLogItem{
			AdminLog: log,
			Staff:    user,
		})
	}
	return
}
